// State management
const state = {
    selectedTags: new Set(),
    tagsJSON: {},
    dataJSON: [],
    filteredData: [],
    recentlyViewed: [],
    searchTerm: '',
    autocompleteIndex: -1
};

const TAG_GROUPS = ['techniques', 'categories', 'targets'];

// Utility functions
const debounce = (func, wait) => {
    let timeout;
    return (...args) => {
        clearTimeout(timeout);
        timeout = setTimeout(() => func(...args), wait);
    };
};

const capitalize = (phrase) =>
    phrase.replace(/_/g, ' ').split(' ')
        // Keep words that already carry casing (SQL, iOS, IoT)
        .map(w => /[A-Z]/.test(w) ? w : w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');

const cleanURL = (url) => {
    const clean = url.replace(/^https?:\/\//, '').replace(/\/+$/, '');
    return clean.length <= 45 ? clean : `${clean.slice(0, 20)}...${clean.slice(-15)}`;
};

const escapeHTML = (str) => str.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const escapeRegExp = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// LocalStorage
function loadFromStorage() {
    try {
        const stored = localStorage.getItem('cyberStationData');
        if (stored) {
            const data = JSON.parse(stored);
            state.recentlyViewed = data.recentlyViewed || [];
        }
    } catch (e) {
        console.error('Error loading storage:', e);
        // Reset corrupted storage
        localStorage.removeItem('cyberStationData');
    }
}

function saveToStorage() {
    try {
        localStorage.setItem('cyberStationData', JSON.stringify({ recentlyViewed: state.recentlyViewed }));
    } catch (e) {
        console.error('Error saving storage:', e);
    }
}

// Recently viewed
function addToRecentlyViewed(toolName) {
    state.recentlyViewed = state.recentlyViewed.filter(n => n !== toolName);
    state.recentlyViewed.unshift(toolName);
    state.recentlyViewed = state.recentlyViewed.slice(0, 10);
    updateRecentlyViewed();
    saveToStorage();
}

function updateRecentlyViewed() {
    const container = document.getElementById('recentlyViewed');
    const itemsContainer = document.getElementById('recentItems');
    
    if (!container || !itemsContainer) return;
    
    if (state.recentlyViewed.length > 0) {
        container.style.display = 'block';
        itemsContainer.innerHTML = state.recentlyViewed.map(name =>
            `<a href="#" class="recent-item" data-name="${escapeHTML(name)}">${escapeHTML(name)}</a>`
        ).join('');
        
        itemsContainer.querySelectorAll('.recent-item').forEach(item => {
            item.addEventListener('click', (e) => {
                e.preventDefault();
                document.getElementById('search').value = item.dataset.name;
                filterItems();
            });
        });
    } else {
        container.style.display = 'none';
    }
}

// Share
async function shareFilters() {
    const params = new URLSearchParams();
    if (state.searchTerm) params.set('q', state.searchTerm);
    if (state.selectedTags.size > 0) params.set('tags', Array.from(state.selectedTags).join(','));
    const url = window.location.origin + window.location.pathname + '?' + params.toString();
    
    const shareBtn = document.getElementById('shareBtn');
    const icon = shareBtn.querySelector('i');
    
    try {
        await navigator.clipboard.writeText(url);
        // Brief check mark confirms the copy
        icon.className = 'bi bi-check2';
        shareBtn.classList.add('is-success');
        setTimeout(() => {
            icon.className = 'bi bi-share';
            shareBtn.classList.remove('is-success');
        }, 2000);
    } catch (e) {
        console.error('Share failed:', e);
    }
}

function loadFromURL() {
    const params = new URLSearchParams(window.location.search);
    if (params.has('q')) document.getElementById('search').value = params.get('q');
    if (params.has('tags')) params.get('tags').split(',').forEach(tag => state.selectedTags.add(tag));
}

// Autocomplete
function showAutocomplete(query) {
    const dropdown = document.getElementById('autocomplete');
    if (!dropdown || !query || query.length < 2) {
        if (dropdown) dropdown.style.display = 'none';
        return;
    }
    
    const matches = state.dataJSON
        .filter(tool => tool.name.toLowerCase().includes(query.toLowerCase()))
        .slice(0, 5);
    
    if (matches.length === 0) {
        dropdown.style.display = 'none';
        return;
    }
    
    dropdown.innerHTML = matches.map(tool => {
        const highlighted = tool.name.replace(
            new RegExp(escapeRegExp(query), 'gi'),
            match => `<strong>${match}</strong>`
        );
        return `<div class="autocomplete-item" data-name="${tool.name}">${highlighted}</div>`;
    }).join('');
    
    dropdown.style.display = 'block';
    state.autocompleteIndex = -1;
    
    dropdown.querySelectorAll('.autocomplete-item').forEach(item => {
        item.addEventListener('click', () => {
            document.getElementById('search').value = item.dataset.name;
            dropdown.style.display = 'none';
            filterItems();
        });
    });
}

const debouncedAutocomplete = debounce(showAutocomplete, 200);

// Active chips
function updateActiveChips() {
    const chipsSection = document.getElementById('activeChips');
    const chipsContainer = chipsSection?.querySelector('.chips-container');
    
    if (!chipsSection || !chipsContainer) return;
    
    if (state.selectedTags.size === 0 && !state.searchTerm) {
        chipsSection.style.display = 'none';
        return;
    }
    
    chipsSection.style.display = 'flex';
    chipsContainer.innerHTML = '';
    
    if (state.searchTerm) {
        const chip = document.createElement('div');
        chip.className = 'filter-chip';
        chip.innerHTML = `<span>Search: ${escapeHTML(state.searchTerm)}</span><i class="bi bi-x"></i>`;
        chip.addEventListener('click', () => {
            document.getElementById('search').value = '';
            state.searchTerm = '';
            filterItems();
        });
        chipsContainer.appendChild(chip);
    }
    
    state.selectedTags.forEach(tag => {
        const chip = document.createElement('div');
        chip.className = 'filter-chip';
        chip.innerHTML = `<span>${escapeHTML(capitalize(tag))}</span><i class="bi bi-x"></i>`;
        chip.addEventListener('click', () => {
            const btn = document.querySelector(`#filters button[data-tag="${CSS.escape(tag)}"]`);
            if (btn) btn.click();
        });
        chipsContainer.appendChild(chip);
    });
}

// Update results count
function updateResultsCount(visible, total) {
    const resultsCount = document.getElementById('resultsCount');
    
    if (resultsCount) {
        resultsCount.innerHTML = `Showing <strong>${visible}</strong> of ${total} tools`;
    }
}

// Data loading
async function loadJSON(url) {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Loading ${url} failed: HTTP ${response.status}`);
    return response.json();
}

async function initializeApp() {
    try {
        loadFromStorage();
        loadFromURL();
        
        const [tags, data] = await Promise.all([loadJSON('data/tags.json'), loadJSON('data/data.json')]);
        
        if (tags) {
            state.tagsJSON = tags;
            // Drop unknown tags from a shared URL so no chip shows a filter that does nothing
            const known = new Set(TAG_GROUPS.flatMap(group => tags[group] || []));
            state.selectedTags.forEach(tag => { if (!known.has(tag)) state.selectedTags.delete(tag); });
            generateFilters();
        }
        
        if (Array.isArray(data)) {
            // Always A-Z (data.json is not fully sorted); filtering keeps this order
            state.dataJSON = data.sort((a, b) => a.name.localeCompare(b.name));
            state.filteredData = [...data];
            renderFilteredItems();
        }
        
        document.getElementById('loadingOverlay')?.classList.add('hidden');
        
        if (state.selectedTags.size > 0 || document.getElementById('search')?.value) {
            state.selectedTags.forEach(tag => {
                const btn = document.querySelector(`#filters button[data-tag="${CSS.escape(tag)}"]`);
                if (btn) btn.classList.add('active');
            });
            filterItems();
        }
        
        updateRecentlyViewed();
        
    } catch (error) {
        console.error('Failed to initialize:', error);
        document.getElementById('loadingOverlay')?.classList.add('hidden');
    }
}

// Render functions
function renderFilteredItems() {
    const dataList = document.getElementById('dataList');
    if (!dataList) return;

    dataList.innerHTML = '';

    if (state.filteredData.length === 0) {
        document.getElementById('noResults').style.display = 'block';
        dataList.style.display = 'none';
        return;
    }

    document.getElementById('noResults').style.display = 'none';
    dataList.style.display = 'grid';

    state.filteredData.forEach(item => dataList.appendChild(createListItem(item)));

    updateResultsCount(state.filteredData.length, state.dataJSON.length);
}

function createListItem(item) {
    const listItem = document.createElement('div');
    listItem.classList.add('list-item');
    listItem.setAttribute('role', 'listitem');

    listItem.innerHTML = `
        <div class="card-header-actions">
            <div class="title">
                <a href="${item.url}" target="_blank" rel="noopener noreferrer" class="title-link" data-name="${item.name}">${item.name || 'Unnamed Tool'}</a>
            </div>
            <div class="card-actions">
                <a href="${item.source || item.url}" target="_blank" rel="noopener noreferrer"
                   class="btn-card-action" title="View Source Code" aria-label="View source for ${item.name}">
                    <i class="bi bi-code-slash"></i>
                </a>
            </div>
        </div>
        <div class="description">${item.description || 'No description available'}</div>
        <a href="${item.url}" target="_blank" rel="noopener noreferrer" class="card-url"
           data-name="${item.name}" aria-label="Visit ${item.name}">
            ${cleanURL(item.url || 'No URL')}
            <i class="bi bi-box-arrow-up-right external-icon"></i>
        </a>
        <div class="card-tags">${generateTags(item)}</div>
    `;

    // Event listeners
    listItem.querySelectorAll('a[data-name]').forEach(link => {
        link.addEventListener('click', () => addToRecentlyViewed(item.name));
    });

    return listItem;
}

const TAG_CLASS = { techniques: 'tag-technique', categories: 'tag-category', targets: 'tag-target' };

// Same component as the filter buttons, so a selected tag reads as active on cards too
const tagButton = (tag, group) =>
    `<button type="button" class="tag ${TAG_CLASS[group]} ${state.selectedTags.has(tag) ? 'active' : ''}" data-tag="${tag}" aria-label="Filter by ${capitalize(tag)}">${capitalize(tag)}</button>`;

function generateTags(item) {
    return TAG_GROUPS.flatMap(group => (item[group] || []).map(tag => tagButton(tag, group))).join('');
}

function generateFilters() {
    const filterList = document.getElementById('filters');
    if (!filterList) return;

    filterList.innerHTML = '';

    // Categories always starts closed; on phones every group does, so the tools sit near the top
    const isPhone = window.matchMedia('(max-width: 767.98px)').matches;
    const sections = [
        { title: 'Techniques', key: 'techniques', collapsible: isPhone },
        { title: 'Targets', key: 'targets', collapsible: isPhone },
        { title: 'Categories', key: 'categories', collapsible: true }
    ];

    sections.forEach(section => {
        if (state.tagsJSON[section.key]) {
            const filterSection = createFilterSection(
                section.title,
                state.tagsJSON[section.key],
                section.key,
                section.collapsible
            );
            filterList.appendChild(filterSection);
        }
    });
}

function createFilterSection(title, tags, group, collapsible = false) {
    // Collapsible groups render as a closed <details> so the tools stay above the fold
    const section = document.createElement(collapsible ? 'details' : 'div');
    section.classList.add('filter-item');

    section.innerHTML = `
        ${collapsible ? `<summary class="title">${title} (${tags.length})</summary>` : `<div class="title">${title}</div>`}
        <div>${tags.map(tag => tagButton(tag, group)).join('')}</div>
    `;

    section.querySelectorAll('button[data-tag]').forEach(btn => {
        btn.addEventListener('click', () => toggleTagFilter(btn, btn.dataset.tag));
    });

    return section;
}

// Filtering
function toggleTagFilter(button, tag) {
    if (state.selectedTags.has(tag)) {
        state.selectedTags.delete(tag);
        button.classList.remove('active');
    } else {
        state.selectedTags.add(tag);
        button.classList.add('active');
    }
    filterItems();
}

function resetFilters() {
    state.selectedTags.clear();
    state.searchTerm = '';
    
    const searchInput = document.getElementById('search');
    if (searchInput) searchInput.value = '';
    
    document.querySelectorAll('#filters button[data-tag]').forEach(btn => {
        btn.classList.remove('active');
    });
    
    filterItems();
}

function filterItems() {
    const searchFilter = document.getElementById('search')?.value.trim().toLowerCase() || '';
    state.searchTerm = searchFilter;

    // OR within a tag group, AND across groups
    const selectedByGroup = TAG_GROUPS.map(group =>
        [group, (state.tagsJSON[group] || []).filter(tag => state.selectedTags.has(tag))]);

    state.filteredData = state.dataJSON.filter(item => {
        const title = (item.name || '').toLowerCase();
        const description = (item.description || '').toLowerCase();

        const matchesSearch = !searchFilter || title.includes(searchFilter) || description.includes(searchFilter);
        const matchesTags = selectedByGroup.every(([group, selected]) =>
            selected.length === 0 || selected.some(tag => (item[group] || []).includes(tag)));

        return matchesSearch && matchesTags;
    });

    renderFilteredItems();
    updateActiveChips();
    
    const clearBtn = document.getElementById('clearSearch');
    if (clearBtn) clearBtn.style.display = searchFilter ? 'block' : 'none';
}

const debouncedFilter = debounce(filterItems, 200);

// Event handlers
function setupSearch() {
    const searchInput = document.getElementById('search');
    const clearBtn = document.getElementById('clearSearch');
    const autocomplete = document.getElementById('autocomplete');
    
    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            debouncedFilter();
            debouncedAutocomplete(e.target.value);
        });
        
        searchInput.addEventListener('keydown', (e) => {
            const items = document.querySelectorAll('.autocomplete-item');
            
            if (e.key === 'ArrowDown') {
                e.preventDefault();
                state.autocompleteIndex = Math.min(state.autocompleteIndex + 1, items.length - 1);
                updateAutocompleteSelection(items);
            } else if (e.key === 'ArrowUp') {
                e.preventDefault();
                state.autocompleteIndex = Math.max(state.autocompleteIndex - 1, -1);
                updateAutocompleteSelection(items);
            } else if (e.key === 'Enter' && state.autocompleteIndex >= 0) {
                e.preventDefault();
                items[state.autocompleteIndex]?.click();
            } else if (e.key === 'Escape') {
                if (autocomplete) autocomplete.style.display = 'none';
                if (searchInput.value) {
                    searchInput.value = '';
                    filterItems();
                } else {
                    searchInput.blur();
                }
            }
        });
    }
    
    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            if (searchInput) {
                searchInput.value = '';
                searchInput.focus();
            }
            if (autocomplete) autocomplete.style.display = 'none';
            filterItems();
        });
    }
    
    document.addEventListener('click', (e) => {
        if (autocomplete && searchInput && !searchInput.contains(e.target) && !autocomplete.contains(e.target)) {
            autocomplete.style.display = 'none';
        }
    });
}

function updateAutocompleteSelection(items) {
    items.forEach((item, index) => {
        item.classList.toggle('active', index === state.autocompleteIndex);
    });
}

function setupCardInteractions() {
    const dataList = document.getElementById('dataList');
    if (!dataList) return;

    dataList.addEventListener('click', (event) => {
        const tag = event.target.closest('.tag')?.dataset.tag;
        if (tag) document.querySelector(`#filters button[data-tag="${CSS.escape(tag)}"]`)?.click();
    });
}

function setupBackToTop() {
    const btn = document.getElementById('backToTop');
    if (!btn) return;

    window.addEventListener('scroll', () => {
        btn.classList.toggle('visible', window.scrollY > 300);
    });

    btn.addEventListener('click', () => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    });
}

function setupKeyboardShortcuts() {
    document.addEventListener('keydown', (e) => {
        if (e.target.matches('input, textarea')) return;
        
        if (e.key === '/') {
            e.preventDefault();
            document.getElementById('search')?.focus();
        }
    });
}

function setupButtons() {
    document.getElementById('shareBtn')?.addEventListener('click', shareFilters);
    document.getElementById('clearAllFilters')?.addEventListener('click', resetFilters);
    document.getElementById('resetFromEmpty')?.addEventListener('click', resetFilters);
}

function initializeEventListeners() {
    setupSearch();
    setupCardInteractions();
    setupBackToTop();
    setupKeyboardShortcuts();
    setupButtons();
}

// Initialize
document.addEventListener('DOMContentLoaded', async () => {
    await initializeApp();
    initializeEventListeners();
});

